// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.agent.notificationimport android.app.Notificationimport android.app.PendingIntentimport android.app.RemoteInputimport android.content.Intentimport android.os.Bundleimport android.service.notification.NotificationListenerServiceimport android.service.notification.StatusBarNotificationimport timber.log.Timberimport java.util.Collections/** * NOUS — Notification Listener Service (Module 9 v1 — Step 9.7, P0 fix). * * REAL Android `NotificationListenerService` implementation. Previously the * `AndroidManifest.xml` declared this service but **no Kotlin class existed** — * which would crash on `PackageManager` service binding at runtime. This file * fixes that P0 by providing the actual class. * * ## Real Android APIs used * * | Operation | API | * |-----------|-----| * | Lifecycle | `NotificationListenerService.onListenerConnected()` / `onListenerDisconnected()` | * | Receive  | `onNotificationPosted(StatusBarNotification)` / `onNotificationRemoved(...)` | * | Dismiss  | `cancelNotification(key)` (API 21+, deprecated in 33 but still functional) | * | Reply    | `Notification.actions[]` + `RemoteInput` + `action.actionIntent.send()` | * | Enumerate| `getActiveNotifications()` | * * ## What we extract * * For every posted notification, we capture (no PII logged): *  - `packageName` — the app that posted it (e.g., `com.whatsapp`). *  - `title` — from `Notification.EXTRA_TITLE`. *  - `text` — from `Notification.EXTRA_TEXT` (falls back to `EXTRA_BIG_TEXT`). *  - `timestampMs` — `StatusBarNotification.getPostTime()`. *  - `key` — `StatusBarNotification.getKey()` (used for dismiss + reply). *  - `replyAction` — the first `Notification.Action` carrying a `RemoteInput` *    (cached so we don't have to re-walk `actions` on reply). * * ## Privacy * *  - The cache is **RAM-only** — never written to disk, never logged in full. *  - On `onNotificationRemoved`, the entry is evicted from the cache. *  - The cache is bounded to [MAX_CACHE_SIZE] = 100 entries (FIFO via *    `LinkedHashMap.removeEldestEntry`). *  - The `BankingAppGuard` blacklist is consulted in `onNotificationPosted` — *    notifications from banking apps are dropped immediately (no cache, no *    log) to enforce the privacy hard-line. * * ## Hilt wiring * * `NotificationListenerService` is instantiated by the Android framework * (same as `AccessibilityService`), so we cannot `@Inject` into it. The * active instance is exposed via the [activeInstance] companion-object * `@Volatile` field — the same pattern used by `AccessibilityServiceRegistry`. * * User MUST enable it manually in Settings → Notification Access → NOUS. * * @see <a href="docs/strategy/module-9-agent-strategy-v1.md">§Step 9.7: Notification Listener</a> */class NousNotificationListenerService : NotificationListenerService() {    /**     * One captured notification. Pure data — no Android references held.     */    data class CapturedNotification(        val key: String,        val packageName: String,        val title: String?,        val text: String?,        val timestampMs: Long,    )    companion object {        private const val TAG = "NousNotifListener"        /** Maximum number of notifications held in the in-memory LRU cache. */        const val MAX_CACHE_SIZE = 100        /**         * The currently-connected listener instance, or null if the user         * hasn't enabled NOUS in Settings → Notification Access.         *         * `@Volatile` for visibility across threads (the listener runs on a         * binder thread; readers run on the main / IO dispatcher).         */        @Volatile        private var activeInstance: NousNotificationListenerService? = null        /**         * True if the listener is connected (user has granted Notification Access).         */        fun isActive(): Boolean = activeInstance != null        /**         * Get a snapshot of the cached notifications (most-recent-first).         *         * Returns an empty list if the listener isn't connected. Safe to         * call from any thread.         */        fun snapshot(): List<CapturedNotification> {            val instance = activeInstance ?: return emptyList()            return instance.getSnapshot()        }        /**         * Find a cached notification by key.         *         * @return the [CapturedNotification] for `key`, or null if the listener         *         isn't connected or `key` is not in the cache.         */        fun find(key: String): CapturedNotification? {            val instance = activeInstance ?: return null            return instance.findInCache(key)        }        /**         * Dismiss a notification by its key.         *         * Calls `cancelNotification(key)` on the listener. Requires the user         * to have granted Notification Access.         *         * @return true if the dismiss call was dispatched (the notification         *         may still be visible if the source app reposts it).         */        fun dismissNotification(key: String): Boolean {            val instance = activeInstance ?: run {                Timber.tag(TAG).w("Cannot dismiss — notification listener not connected.")                return false            }            return instance.dismissByKey(key)        }        /**         * Reply to a notification via its `RemoteInput` action.         *         * Walks `Notification.actions`, finds the first action carrying a         * `RemoteInput`, builds a result intent with the reply text, and         * fires `action.actionIntent.send()`.         *         * @param key the notification key (from `StatusBarNotification.getKey()`).         * @param reply the text to send as the reply.         * @return true if the reply intent was dispatched successfully.         */        fun replyToNotification(key: String, reply: String): Boolean {            val instance = activeInstance ?: run {                Timber.tag(TAG).w("Cannot reply — notification listener not connected.")                return false            }            return instance.replyByKey(key, reply)        }    }    /**     * In-memory LRU cache of recent notifications.     *     * `LinkedHashMap(accessOrder = true)` + `removeEldestEntry` gives us a     * bounded LRU: when `size > MAX_CACHE_SIZE`, the eldest entry (least     * recently accessed) is evicted on the next `put`. Wrapped in     * `Collections.synchronizedMap` because `onNotificationPosted` runs on a     * binder thread while readers run elsewhere.     */    private val cache: MutableMap<String, CapturedNotification> =        Collections.synchronizedMap(object : LinkedHashMap<String, CapturedNotification>(            16, 0.75f, true /* accessOrder */,        ) {            override fun removeEldestEntry(eldest: MutableMap.MutableEntry<String, CapturedNotification>?): Boolean {                return size > MAX_CACHE_SIZE            }        })    // ─── Lifecycle ───────────────────────────────────────────────────────────    override fun onListenerConnected() {        super.onListenerConnected()        activeInstance = this        Timber.tag(TAG).i("Notification listener connected.")    }    override fun onListenerDisconnected() {        Timber.tag(TAG).i("Notification listener disconnected.")        activeInstance = null        synchronized(cache) { cache.clear() }        super.onListenerDisconnected()    }    // ─── Event handlers ──────────────────────────────────────────────────────    /**     * Called by Android when a new notification is posted.     *     * We extract the safe metadata + cache it. We do NOT cache notifications     * from banking apps (privacy hard-line).     */    override fun onNotificationPosted(sbn: StatusBarNotification?) {        if (sbn == null) return        val packageName = sbn.packageName?.toString() ?: return        // Privacy hard-line: drop banking-app notifications silently.        if (com.roshan.persona.agent.guard.BankingAppGuard.BLACKLIST.contains(packageName)) {            Timber.tag(TAG).v("Dropping notification from blacklisted banking app: $packageName.")            return        }        val captured = extractNotification(sbn)        synchronized(cache) { cache[captured.key] = captured }        Timber.tag(TAG).d("Posted: pkg=%s, title=%s, ts=%d.", captured.packageName, captured.title, captured.timestampMs)    }    /**     * Called by Android when a notification is removed (user swiped it, app     * cancelled it, or user dismissed all).     */    override fun onNotificationRemoved(sbn: StatusBarNotification?) {        if (sbn == null) return        // sbn.key is @NonNull (always present, API 21+).        val key: String = sbn.key        synchronized(cache) { cache.remove(key) }        Timber.tag(TAG).d("Removed: key=%s.", key)    }    // ─── Public API (called via companion) ───────────────────────────────────    /**     * Get a snapshot of the cache (most-recent-first by access order).     */    internal fun getSnapshot(): List<CapturedNotification> {        return synchronized(cache) { cache.values.toList() }    }    /**     * Find a cached notification by key.     */    internal fun findInCache(key: String): CapturedNotification? {        return synchronized(cache) { cache[key] }    }    /**     * Dismiss a notification by its key (REAL Android API).     *     * `cancelNotification(String key)` is deprecated in API 33 but still     * functional; the deprecation simply marks that the new     * `cancelNotifications(String[])` is preferred for batch operations.     * Single-dismiss is the documented use case for the deprecated overload.     */    @Suppress("DEPRECATION")    internal fun dismissByKey(key: String): Boolean {        return try {            cancelNotification(key)            Timber.tag(TAG).d("Dismiss dispatched for key=%s.", key)            true        } catch (e: SecurityException) {            Timber.tag(TAG).e(e, "SecurityException dismissing notification (listener disconnected?).")            false        } catch (e: IllegalStateException) {            Timber.tag(TAG).e(e, "IllegalStateException dismissing notification.")            false        }    }    /**     * Reply to a notification by its key (REAL Android API — RemoteInput).     *     * 1. Look up the active `StatusBarNotification` via `getActiveNotifications()`.     * 2. Walk its `Notification.actions` for the first action carrying a     *    `RemoteInput`.     * 3. Build the result intent: `RemoteInput.addInputToIntent(remoteInput, srcIntent, reply)`.     * 4. Fire `action.actionIntent.send(context, 0, resultIntent)`.     *     * Returns false if the notification is gone, has no reply action, or the     * `PendingIntent.send()` call throws.     */    internal fun replyByKey(key: String, reply: String): Boolean {        val sbn: StatusBarNotification = try {            getActiveNotifications().firstOrNull { it.key == key }        } catch (e: SecurityException) {            Timber.tag(TAG).e(e, "SecurityException getting active notifications (listener disconnected?).")            return false        } catch (e: Exception) {            Timber.tag(TAG).e(e, "Unexpected error getting active notifications.")            return false        } ?: run {            Timber.tag(TAG).w("Cannot reply — notification no longer active: key=%s.", key)            return false        }        val notification: Notification = sbn.notification        val actions: Array<Notification.Action> = notification.actions ?: run {            Timber.tag(TAG).w("Notification has no actions: key=%s.", key)            return false        }        // Find the first action with a RemoteInput (the "reply" action).        val replyAction: Notification.Action = actions.firstOrNull { action ->            action.remoteInputs?.any { it != null } == true        } ?: run {            Timber.tag(TAG).w("Notification has no RemoteInput action (not replyable): key=%s.", key)            return false        }        val remoteInput: RemoteInput = replyAction.remoteInputs?.firstOrNull { it != null }            ?: run {                Timber.tag(TAG).w("Reply action has no RemoteInput: key=%s.", key)                return false            }        // Build the result intent carrying the reply text.        val resultIntent = Intent().apply {            val bundle = Bundle()            bundle.putCharSequence(remoteInput.resultKey, reply)            // addResultsToIntent mutates + returns the intent (it adds the            // clipped-data slot that the source app's BroadcastReceiver            // extracts).            RemoteInput.addResultsToIntent(arrayOf(remoteInput), this, bundle)        }        val pendingIntent = replyAction.actionIntent        if (pendingIntent == null) {            Timber.tag(TAG).w("Reply action has no PendingIntent: key=%s.", key)            return false        }        return try {            pendingIntent.send(this, 0, resultIntent)            Timber.tag(TAG).d("Reply dispatched for key=%s (len=%d).", key, reply.length)            true        } catch (e: PendingIntent.CanceledException) {            Timber.tag(TAG).e(e, "PendingIntent canceled while replying to key=%s.", key)            false        } catch (e: Exception) {            Timber.tag(TAG).e(e, "Unexpected error replying to key=%s.", key)            false        }    }    // ─── Helpers ─────────────────────────────────────────────────────────────    /**     * Extract the safe metadata from a `StatusBarNotification`.     *     * `sbn.key` and `sbn.notification` are both `@NonNull` (always present,     * API 21+), so this function always returns a non-null     * [CapturedNotification]. The caller still does `?: return` defensively     * in case future Android versions change nullability contracts.     */    private fun extractNotification(sbn: StatusBarNotification): CapturedNotification {        // sbn.key is @NonNull (always present, API 21+).        val key: String = sbn.key        val packageName: String = sbn.packageName?.toString() ?: "unknown"        // sbn.notification is @NonNull. getExtras() is @Nullable.        val extras: Bundle? = sbn.notification.extras        val title = extras?.getCharSequence(Notification.EXTRA_TITLE)?.toString()        val text = (extras?.getCharSequence(Notification.EXTRA_TEXT)?.toString()            ?: extras?.getCharSequence(Notification.EXTRA_BIG_TEXT)?.toString())        return CapturedNotification(            key = key,            packageName = packageName,            title = title,            text = text,            timestampMs = sbn.postTime,        )    }}
